import Image from "next/image";
import Link from "next/link";
import type { BlogPost } from "@/types/blog";
import styles from "./blog-card.module.css";

const CATEGORY_LABELS: Record<string, string> = {
  cro: "CRO",
  shopify: "Shopify",
  "ui-ux-design": "UI/UX Design",
  "web-development": "Web Development",
  "white-label-outsourcing": "White-Label & Outsourcing",
  wordpress: "WordPress",
};

interface BlogCardProps {
  post: BlogPost;
}

export function BlogCard({ post }: BlogCardProps) {
  const categoryLabel = CATEGORY_LABELS[post.category] ?? post.category;

  return (
    <article className={styles.card}>
      {/* Image area — cms-link.blog-link */}
      <Link href={`/blog/${post.slug}`} className={styles.imageLink} tabIndex={-1} aria-hidden="true">
        <Image
          src={post.image}
          alt={`${post.title} cover`}
          fill
          sizes="(max-width: 767px) 100vw, (max-width: 1280px) 50vw, 33vw"
          className={styles.image}
          loading="lazy"
        />
      </Link>

      {/* content_card-block-blog */}
      <div className={styles.body}>
        {/* content_card-header */}
        <div className={styles.header}>
          <Link href={`/blog/${post.slug}`} style={{ textDecoration: "none", color: "inherit" }}>
            {/* content_card-title.blog-post-title */}
            <h3 className={styles.title}>{post.title}</h3>
            {/* blog-cat-name */}
            <p className={styles.category}>{categoryLabel}</p>
          </Link>
        </div>

        {/* paragraph.text-left.blog-desc */}
        <p className={styles.description}>{post.shortDescription}</p>

        {/* a-gulf-book.blog-read-btn */}
        <Link href={`/blog/${post.slug}`} className={styles.readBtn}>
          Read Article
        </Link>
      </div>
    </article>
  );
}

