/* ============================================================
   BlogCard — blog-card.module.css
   Matches Webflow .content_card-blog + .content_card-block-blog
   ============================================================ */

/* content_card-blog */
.card {
  grid-column-gap: 1rem;
  grid-row-gap: 1rem;
  color: #000;
  background-color: transparent;
  border: 1px solid rgba(33, 207, 255, 0.23);
  border-radius: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr;
  grid-auto-columns: 1fr;
  align-items: start;
  width: 100%;
  height: 240px;
  min-height: auto;
  max-height: none;
  padding: 10px;
  text-decoration: none;
  display: grid;
  overflow: hidden;
  transition: box-shadow 0.2s ease;
}

.card:hover {
  box-shadow: 0 4px 20px rgba(9, 34, 69, 0.12);
}

/* cms-link.blog-link → image link area */
.imageLink {
  display: block;
  height: 100%;
  overflow: hidden;
  text-decoration: none;
  border-radius: 15px;
}

/* content_card-image-blog */
.image {
  object-fit: cover;
  border-radius: 15px;
  width: 100%;
  height: 100%;
  display: block;
  transition: transform 0.3s ease;
}

.card:hover .image {
  transform: scale(1.03);
}

/* content_card-block-blog */
.body {
  grid-column-gap: 0.3rem;
  grid-row-gap: 0.3rem;
  grid-template-rows: auto auto;
  grid-template-columns: 1fr;
  grid-auto-columns: 1fr;
  align-content: center;
  place-items: center start;
  margin-top: 10px;
  padding: 0.5rem 0 0;
  display: grid;
}

/* content_card-header */
.header {
  color: var(--color-text-primary);
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 30px;
  display: flex;
  text-decoration: none;
  width: 100%;
}

/* content_card-title.blog-post-title */
.title {
  color: var(--color-text-primary);
  text-align: left;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 25px;
  font-weight: 700;
  line-height: 35px;
  margin: 0;
  text-decoration: none;
}

/* blog-cat-name */
.category {
  color: transparent;
  background-image: linear-gradient(#21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
  text-align: left;
  margin-bottom: 0;
  margin-top: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
}

/* paragraph.text-left.blog-desc */
.description {
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1.125rem;
  color: var(--color-text-secondary);
  line-height: 28px;
  text-align: left;
  margin: 4px 0 0;
}

/* a-gulf-book.blog-read-btn */
.readBtn {
  color: #fff;
  width: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  background-color: var(--color-brand-dark);
  background-image: url('/images/webflow/Group-46729-2.svg'),
    linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  margin-top: 8px;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  box-shadow: var(--shadow-card);
  transition: background-color 0.2s ease;
}

.readBtn:hover {
  background-color: var(--color-brand-navy);
  background-image: url('/images/webflow/Group-46729-2.svg');
  background-repeat: no-repeat;
  background-size: auto;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .card {
    align-items: start;
    height: 270px;
    min-height: 280px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .card {
    height: 270px;
    min-height: auto;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .card {
    align-items: start;
    min-height: auto;
  }

  .body {
    padding-bottom: 0;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .card {
    min-height: auto;
  }

  .body {
    padding-bottom: 0;
  }
}

/* ============================================================
   max-width: 479px
   ============================================================ */
@media screen and (max-width: 479px) {
  .body {
    padding: 10px 10px 0;
  }

  .card {
    min-height: auto;
  }
}

