import Image from "next/image";
import Link from "next/link";
import type { BlogPost } from "@/types/blog";
import { BlogCard } from "../blog-card";
import styles from "./blog-detail.module.css";

const CATEGORY_LABELS: Record<string, string> = {
  cro: "CRO",
  shopify: "Shopify",
  "ui-ux-design": "UI/UX Design",
  "web-development": "Web Development",
  "white-label-outsourcing": "White-Label & Outsourcing",
  wordpress: "WordPress",
};

interface BlogDetailViewProps {
  post: BlogPost;
  relatedPosts: BlogPost[];
}

export function BlogDetailView({ post, relatedPosts }: BlogDetailViewProps) {
  const categoryLabel = CATEGORY_LABELS[post.category] ?? post.category;

  return (
    <section className={styles.page}>
      <div className={styles.container}>
        {/* Back link */}
        <Link href="/blog" className={styles.backLink}>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
          >
            <polyline points="15 18 9 12 15 6" />
          </svg>
          Back to Blog
        </Link>

        {/* blog-detail-top-grid */}
        <div className={styles.topGrid}>
          {/* ── Main content column ── */}
          <main className={styles.mainCol}>
            {/* blog-detail-cat-name-top */}
            <p className={styles.catNameTop}>{categoryLabel}</p>

            {/* content_card-title.blog-detail-title */}
            <h1 className={styles.postTitle}>{post.title}</h1>

            {/* blog-detail-cat-name */}
            <p className={styles.catName}>{post.shortDescription}</p>

            {/* blog-detail-image */}
            <Image
              src={post.image}
              alt={`${post.title} cover image`}
              width={800}
              height={450}
              className={styles.coverImage}
              priority
              sizes="(max-width: 991px) 100vw, 800px"
            />

            {/* Rich text body from CMS */}
            <div
              className={styles.body}
              dangerouslySetInnerHTML={{ __html: post.content ?? "" }}
            />
          </main>

          {/* ── Sidebar ── */}
          <aside className={styles.sidebar} aria-label="Article sidebar">
            {/* About the article */}
            <div className={styles.sidebarBlock}>
              <p className={styles.sidebarLabel}>Category</p>
              <p className={styles.sidebarValue}>{categoryLabel}</p>
            </div>

            {/* CTA gradient block */}
            <div className={styles.sidebarCta}>
              <h2 className={styles.sidebarCtaTitle}>
                Scale Your Agency with White-Label Delivery
              </h2>
              <Link href="/book-a-demo" className={styles.sidebarCtaBtn}>
                Book a Demo
              </Link>
            </div>
          </aside>
        </div>

        {/* Related posts */}
        {relatedPosts.length > 0 && (
          <section className={styles.relatedSection} aria-label="Related articles">
            <h2 className={styles.relatedTitle}>Related Articles</h2>
            <ul className={styles.relatedGrid} role="list">
              {relatedPosts.map((related) => (
                <li key={related.slug}>
                  <BlogCard post={related} />
                </li>
              ))}
            </ul>
          </section>
        )}
      </div>
    </section>
  );
}

