/* ============================================================
   BlogDetail — blog-detail.module.css
   Matches Webflow .blog-detail-page.new + .blog-detail-top-grid
   ============================================================ */

/* blog-detail-page.new */
.page {
  background-color: transparent;
  background-image: none;
  border-bottom-right-radius: 0;
  border-bottom-left-radius: 0;
  padding: 80px 3% 80px;
  display: block;
  position: relative;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
}

/* blog-detail-top-grid */
.topGrid {
  grid-column-gap: 50px;
  grid-row-gap: 50px;
  grid-template-rows: auto;
  grid-template-columns: minmax(200px, 800px) minmax(200px, 325px);
  display: grid;
  align-items: start;
}

/* ── Left: main content ── */
.mainCol {
  display: flex;
  flex-direction: column;
}

/* blog-detail-cat-name-top (gradient category above title) */
.catNameTop {
  color: transparent;
  background-image: linear-gradient(#21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
  text-align: left;
  margin-bottom: 10px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* content_card-title.blog-detail-title */
.postTitle {
  color: var(--color-text-primary);
  margin-bottom: 10px;
  margin-top: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 50px;
}

/* blog-detail-cat-name */
.catName {
  color: var(--color-text-secondary);
  text-align: left;
  margin-bottom: 10px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
}

/* blog-detail-image */
.coverImage {
  object-fit: cover;
  border-radius: 20px;
  width: 100%;
  height: auto;
  margin-top: 10px;
  margin-bottom: 20px;
  display: block;
}

/* CMS rich text body */
.body {
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1.125rem;
  color: var(--color-text-secondary);
  line-height: 1.75;
}

.body h4 {
  color: var(--color-text-primary);
  font-size: 1.25rem;
  font-weight: 700;
  margin-top: 2rem;
  margin-bottom: 0.75rem;
  font-family: var(--font-roobert), Arial, sans-serif;
}

.body p {
  margin-top: 0;
  margin-bottom: 1rem;
}

.body strong {
  font-weight: 700;
  color: var(--color-text-primary);
}

/* ── Right: sidebar ── */
.sidebar {
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  flex-flow: column;
  display: flex;
  position: sticky;
  top: 24px;
}

/* blog-detail-sidebar-block */
.sidebarBlock {
  background-color: #fff;
  border-radius: 20px;
  flex: 1;
  padding: 20px;
  box-shadow: var(--shadow-card-soft);
}

.sidebarLabel {
  color: #a3a3a3;
  margin-bottom: 12px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 14px;
}

.sidebarTitle {
  color: var(--color-text-primary);
  margin: 0 0 6px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
}

.sidebarValue {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
}

/* sidebar-sky-block — CTA gradient card */
.sidebarCta {
  background-image: linear-gradient(#21cfff, #019ae6);
  border-radius: 20px;
  padding: 20px;
}

.sidebarCtaTitle {
  color: #fefefe;
  margin-top: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 25px;
  font-weight: 700;
  line-height: 1.2;
}

.sidebarCtaBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-text-primary);
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  border-radius: 0.75rem;
  padding: 0.6rem 1.5rem;
  text-decoration: none;
  margin-top: 12px;
  transition: background-color 0.2s ease;
}

.sidebarCtaBtn:hover {
  background-color: #ffffff;
  color: var(--color-text-primary);
}

/* Related posts */
.relatedSection {
  margin-top: 60px;
  padding-top: 40px;
  border-top: 1px solid rgba(33, 207, 255, 0.23);
}

.relatedTitle {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 24px;
}

/* content_collection-list.blog-detail-list: 3 col */
.relatedGrid {
  grid-column-gap: 16px;
  grid-row-gap: 24px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr;
  grid-auto-columns: 1fr;
  display: grid;
  list-style: none;
  margin: 0;
  padding: 0;
}

/* Back link */
.backLink {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--color-brand-blue);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  margin-bottom: 24px;
}

.backLink:hover {
  color: var(--color-text-primary);
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .topGrid {
    grid-template-columns: minmax(200px, 800px) minmax(200px, 325px);
  }
}

/* ============================================================
   max-width: 991px  (tablet)
   ============================================================ */
@media screen and (max-width: 991px) {
  .topGrid {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: static;
  }

  .postTitle {
    font-size: 32px;
    line-height: 40px;
  }

  .relatedGrid {
    grid-template-columns: 1fr 1fr;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .page {
    padding: 40px 5% 60px;
  }

  .postTitle {
    font-size: 28px;
    line-height: 36px;
  }

  .relatedGrid {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   max-width: 479px
   ============================================================ */
@media screen and (max-width: 479px) {
  .page {
    padding: 30px 5% 60px;
  }

  .postTitle {
    font-size: 24px;
    line-height: 32px;
  }
}

