/* BlogBottomCta — extracted from inline styles */

.section {
  padding: 0 5% 80px;
  position: relative;
  background-color: transparent;
}

.inner {
  max-width: 80rem;
  margin: 0 auto;
}

.body {
  display: flex;
  flex-direction: column;
  gap: 40px;
}

.header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.heading {
  color: var(--color-brand-navy);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 45px;
  margin: 0;
  text-align: center;
}

.subtitle {
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
  color: var(--color-text-muted);
  margin: 0;
  text-align: center;
}

.btnRow {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
  justify-content: center;
}

.btnPrimary {
  color: var(--color-surface);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.75rem;
  background-image: url('/images/webflow/Group-46729-2.svg'), var(--gradient-brand);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border-radius: 0.75rem;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-card);
}

.btnNavy {
  color: var(--color-surface);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.75rem;
  background-color: var(--color-text-primary);
  background-image: url('/images/webflow/Group-46729-1.svg');
  background-position: 94%;
  background-repeat: no-repeat;
  background-size: auto;
  border-radius: 0.75rem;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

@media (max-width: 767px) {
  .grid {
    grid-template-columns: 1fr;
  }

  .heading {
    font-size: 2rem;
  }
}

.card {
  background-color: var(--color-accent-bg);
  border: 1px solid rgba(33, 207, 255, 0.25);
  border-radius: 20px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.cardHeading {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 25px;
  margin: 0 0 7px;
  text-align: left;
}

.cardPara {
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
  color: var(--color-text-secondary);
  margin: 0 0 16px;
}

.cardBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-text-primary);
  color: var(--color-surface);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 700;
  border-radius: 0.75rem;
  padding: 0.6rem 1.25rem;
  text-decoration: none;
  margin-top: 5px;
}

.cardBtn:hover {
  background-color: var(--color-brand-navy);
}

