/* ============================================================
   BlogGrid — blog-grid.module.css
   Matches Webflow .blog-post-sec.new + .filter_grid exactly
   ============================================================ */

/* blog-post-sec.new */
.section {
  background-color: transparent;
  background-image: none;
  border-bottom-right-radius: 0;
  border-bottom-left-radius: 0;
  padding: 0 3% 80px;
  display: block;
  position: relative;
}

/* tabs-container → padding-vertical.padding-xlarge inner */
.tabsContainer {
  width: 100%;
}

/* filt-out */
.filtOut {
  width: 100%;
}

/* filter_grid: default .4fr 1fr */
.filterGrid {
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-rows: auto;
  grid-template-columns: 0.4fr 1fr;
  grid-auto-columns: 1fr;
  align-items: start;
  display: grid;
}

/* ── Sidebar (filter_column.blog-filter-column) ── */
.filterColumn {
  grid-column-gap: 15px;
  grid-row-gap: 15px;
  background-color: transparent;
  flex-flow: column;
  display: flex;
}

/* filter_block.search-block.blog-filter-block */
.searchBlock {
  background-color: #ffffff;
  border-radius: 10px;
  box-shadow: var(--shadow-card-soft);
  padding: 10px;
}

/* filter_block.blog-filter-block */
.filterBlock {
  background-color: #ffffff;
  border-radius: 10px;
  box-shadow: var(--shadow-card-soft);
  padding: 0;
  overflow: hidden;
}

/* filter_block-header.margin-top-0.blog-filter-header */
.filterBlockHeader {
  background-color: transparent;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  padding: 0.5rem 0.8rem;
  display: flex;
  position: relative;
}

/* filter-bar-title.margin-bottom-0 */
.filterBarTitle {
  color: var(--color-brand-navy);
  text-align: left;
  margin-top: 0;
  margin-bottom: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
}

/* filter_reset */
.filterReset {
  color: var(--color-brand-blue);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
}

.filterReset:hover {
  color: var(--color-text-primary);
}

/* filter_options */
.filterOptions {
  padding: 0 0.8rem 0.8rem;
}

/* filter_search-field */
.searchField {
  color: var(--color-text-secondary);
  background-color: #ffffff;
  background-image: url('/images/webflow/Vector-6.svg');
  background-position: 94%;
  background-repeat: no-repeat;
  background-size: 1.5rem;
  border: 1px solid rgba(33, 207, 255, 0.23);
  border-radius: 10px;
  min-width: auto;
  min-height: 45px;
  width: 100%;
  margin-bottom: 0;
  padding: 1rem 1.5rem 1rem 1rem;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  box-shadow: var(--shadow-card);
  box-sizing: border-box;
}

.searchField::placeholder {
  color: #9ca3af;
}

.searchField:focus {
  border-color: var(--color-brand-cyan);
}

/* Category list inside sidebar */
.categoryList {
  display: flex;
  flex-direction: column;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.categoryItem {
  display: flex;
  align-items: center;
  gap: 8px;
}

.categoryCheckbox {
  width: 16px;
  height: 16px;
  border: 1.5px solid #d1d5db;
  border-radius: 3px;
  cursor: pointer;
  accent-color: var(--color-brand-cyan);
  flex-shrink: 0;
}

.categoryLabel {
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 14px;
  color: var(--color-text-primary);
  cursor: pointer;
  line-height: 1.4;
}

.categoryLabelActive {
  color: var(--color-brand-blue);
  font-weight: 600;
}

/* Top Posts */
.topPostsList {
  display: flex;
  flex-direction: column;
  gap: 12px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.topPostItem {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.topPostNumber {
  color: transparent;
  background-image: linear-gradient(#21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 34px;
  line-height: 44px;
  font-weight: 700;
  flex-shrink: 0;
}

.topPostInner {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.topPostTitle {
  color: var(--color-text-primary);
  text-align: left;
  margin: 0 0 5px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
  text-decoration: none;
}

.topPostTitle:hover {
  color: var(--color-brand-blue);
}

.topPostCat {
  color: #acacac;
  text-align: left;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 12px;
  margin: 0;
}

/* Social icons row */
.socialRow {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 4px 0;
}

.socialLink {
  display: flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
}

.socialLink img {
  width: 24px;
  height: 24px;
}

/* ── Content area (filter_content.blog-filter-content) ── */
.filterContent {
  padding-top: 10px;
}

/* content_collection-list: 2-col grid */
.grid {
  grid-column-gap: 16px;
  grid-row-gap: 24px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr;
  grid-auto-columns: 1fr;
  display: grid;
  list-style: none;
  margin: 0;
  padding: 0;
}

/* Load More btn area */
.loadMoreOuter {
  margin-top: 32px;
  display: flex;
  justify-content: center;
}

/* Empty state */
.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 24px;
  text-align: center;
}

.emptyIcon {
  width: 80px;
  height: auto;
  margin-bottom: 8px;
}

.emptyText {
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  color: var(--color-text-subtle);
  margin: 0;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .filterGrid {
    grid-template-columns: minmax(305px, 305px) 1fr;
  }
}

/* ============================================================
   max-width: 991px  (tablet)
   ============================================================ */
@media screen and (max-width: 991px) {
  .filterGrid {
    grid-column-gap: 1rem;
    grid-template-columns: 0.35fr 1fr;
  }

  .grid {
    grid-row-gap: 16px;
    grid-template-columns: 1fr 1fr;
  }
}

/* ============================================================
   max-width: 767px  (mobile portrait / large)
   ============================================================ */
@media screen and (max-width: 767px) {
  .filterGrid {
    grid-template-columns: 1fr;
  }

  .filterColumn {
    flex-flow: column-reverse;
  }

  .grid {
    grid-row-gap: 20px;
    grid-template-columns: 1fr;
  }

  .section {
    padding-top: 0;
    padding-bottom: 60px;
  }
}

/* ============================================================
   max-width: 479px  (small mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .filterGrid {
    grid-template-columns: minmax(100%, 1fr);
  }

  .section {
    padding-top: 20px;
    padding-bottom: 60px;
  }
}

