/* ============================================================
   BlogHero — blog-hero.module.css
   Matches: .blog-page-banner on blog.html
   ============================================================ */

.section {
  background-color: transparent;
  padding-top: 4rem;
  padding-bottom: 4rem;
  font-weight: 400;
  text-decoration: none;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

/* Inner centering wrapper (.div-wrote-smoke.blogb-smoke) */
.inner {
  text-align: center;
  max-width: 45rem;
  margin-left: auto;
  margin-right: auto;
}

/* H1 (.blog-page-title) */
.heading {
  color: var(--color-brand-navy);
  margin-top: 0;
  padding: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

/* Subtitle (.h1-season-seeing.web-h1) */
.subtitle {
  color: var(--color-text-secondary);
  max-width: 53rem;
  margin-left: auto;
  margin-right: auto;
  margin-top: 0;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  text-decoration: none;
}

/* Badge grid wrapper (.web-job-attention) */
.badgeGridWrap {
  z-index: 1;
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  font-weight: 400;
  text-decoration: none;
  display: flex;
  position: relative;
}

/* Badge grid (.web-ban-grid.mob-2grid.blog-ban-grid) — 3 boxes in a row */
.badgeGrid {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  flex: 0 auto;
  width: auto;
  display: flex;
}

/* Individual badge box (.blog-ban-gridbox) */
.badge {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  background-color: #fff;
  border-radius: 10px;
  align-items: center;
  width: auto;
  padding: 15px;
  transition: opacity 0.5s ease, transform 0.5s ease;
  display: flex;
  box-shadow: var(--shadow-card);
}

.badgeIcon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
}

.badgeLabel {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
  text-align: left;
  margin: 0;
}

/* CTA button (.div-job-attention > .a-gulf-book) */
.ctaWrap {
  z-index: 1;
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  display: flex;
  position: relative;
}

