/* ============================================================
   BlogDetail — blog-detail.module.css
   Webflow ref: .blog-detail-page.new + .blog-detail-top-grid
   See webflow.css L18133-L18316
   ============================================================ */

/* blog-detail-page.new */
.page {
  background-color: transparent;
  background-image: none;
  border-bottom-right-radius: 0;
  border-bottom-left-radius: 0;
  padding: 80px 3% 80px;
  display: block;
  position: relative;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
}

/* blog-detail-top-grid */
.topGrid {
  grid-column-gap: 50px;
  grid-row-gap: 50px;
  grid-template-rows: auto;
  grid-template-columns: minmax(200px, 800px) minmax(200px, 325px);
  display: grid;
