}

.sidebarCtaTitle {
  color: #fefefe;
  margin-top: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 25px;
  font-weight: 700;
  line-height: 1.2;
}

.sidebarCtaBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-text-primary);
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  border-radius: 0.75rem;
  padding: 0.6rem 1.5rem;
  text-decoration: none;
  margin-top: 12px;
  transition: background-color 0.2s ease;
}

.sidebarCtaBtn:hover {
  background-color: #ffffff;
  color: var(--color-text-primary);
}

/* Related posts */
.relatedSection {
  margin-top: 60px;
  padding-top: 40px;
  border-top: 1px solid rgba(33, 207, 255, 0.23);
}

.relatedTitle {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 24px;
}

/* content_collection-list.blog-detail-list: 3 col */
.relatedGrid {
  grid-column-gap: 16px;
  grid-row-gap: 24px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr;
  grid-auto-columns: 1fr;
  display: grid;
  list-style: none;
  margin: 0;
  padding: 0;
}

/* Back link */
.backLink {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--color-brand-blue);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  margin-bottom: 24px;
}

.backLink:hover {
  color: var(--color-text-primary);
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .topGrid {
    grid-template-columns: minmax(200px, 800px) minmax(200px, 325px);
  }
}

/* ============================================================
   max-width: 991px  (tablet)
   ============================================================ */
@media screen and (max-width: 991px) {
  .topGrid {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: static;
  }

  .postTitle {
    font-size: 32px;
    line-height: 40px;
  }

  .relatedGrid {
    grid-template-columns: 1fr 1fr;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .page {
    padding: 40px 5% 60px;
  }

  .postTitle {
    font-size: 28px;
    line-height: 36px;
  }

  .relatedGrid {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   max-width: 479px
   ============================================================ */
@media screen and (max-width: 479px) {
  .page {
    padding: 30px 5% 60px;
  }

  .postTitle {
    font-size: 24px;
    line-height: 32px;
  }
}
